import type { PostRepository } from "../application/post-queries"
import type { PostDetail } from "../domain/post"
import data from "./data/posts.json"

// Real fanpage posts, generated by `npm run import:posts` (scripts/import-posts.mjs). Stands in for the Go API.
type Row = (typeof data)[number] & { campaignSlug?: string }

const toDetail = (r: Row): PostDetail => ({
  slug: r.slug,
  title: r.title,
  excerpt: r.excerpt,
  tag: r.topic,
  publishedOn: r.publishedOn,
  cover: { src: r.images[0], alt: r.title },
  gallery: r.images.slice(1).map((src, i) => ({ src, alt: `${r.title} — ảnh ${i + 2}` })),
  blocks: r.blocks as PostDetail["blocks"],
  campaignSlug: r.campaignSlug,
})

const posts = (data as Row[]).map(toDetail)

// Home highlights: the Thiềng Liềng stories (best photography). Matched by the end of the Facebook post id.
const featuredIds = ["fs5h5pUl", "H3HAe7dl", "kYgTDPZl"]
const idOf = new Map((data as Row[]).map((r) => [r.slug, r.sourceId]))

export const jsonPostRepository: PostRepository = {
  async all() {
    return posts
  },
  async featured(limit) {
    const picked = featuredIds.flatMap((id) => posts.filter((p) => idOf.get(p.slug)?.endsWith(id)))
    return (picked.length ? picked : posts).slice(0, limit)
  },
}
